(window.JCPA_DATA=window.JCPA_DATA||{})["accounting"]={"id":"accounting","name":"تنظيم مهنة المحاسبة القانونية","full":"قانون تنظيم مهنة المحاسبة القانونية رقم (73) لسنة 2003","icon":"📒","articles":[{"n":"1","chapter":"","notes":[],"source":"يسمى هذا القانون (قانون تنظيم مهنة المحاسبة القانونية لسنة ٢٠٠٣ ) ويعمل به من تاريخ نشره في الجريدة الرسمية .","title":"اسم القانون وبدء العمل به","memo":"⭐ قانون تنظيم مهنة المحاسبة القانونية لسنة ٢٠٠٣\n⭐ يعمل به من تاريخ نشره في الجريدة الرسمية","qs":[{"q":"يعمل بقانون تنظيم مهنة المحاسبة القانونية لسنة ٢٠٠٣ اعتباراً من:","o":["تاريخ نشره في الجريدة الرسمية","تاريخ إقراره من مجلس الأمة","مرور ثلاثين يوماً على نشره في الجريدة الرسمية","بداية السنة المالية التالية لنشره"],"a":0},{"q":"الاسم الذي يسمى به القانون رقم (٧٣) لسنة ٢٠٠٣ هو:","o":["قانون تنظيم مهنة المحاسبة القانونية","قانون مهنة تدقيق الحسابات","قانون جمعية المحاسبين القانونيين الأردنيين","قانون مزاولة مهنة المحاسبة والتدقيق"],"a":0}]},{"n":"2","chapter":"","notes":[],"source":"يكون للكلمات والعبارات التالية حيثما وردت في هذا القانون المعاني المخصصة لها ادناه ما لم تدل القرينة على غير ذلك :-\nالوزير:وزير الصناعة والتجارة .\nالهيئة العليا:الهيئة العليا للمهنة المشكلة بمقتضى احكام هذا القانون .\nالجمعية:جمعية المحاسبين القانونيين الأردنيين المنشأة بمقتضى احكام هذا القانون .\nالهيئة العامة:الهيئة العامة للجمعية .\nالمجلس:مجلس ادارة الجمعية .\nالرئيس:رئيس المجلس .\nالمحاسبة:تطبيق قواعد ومبادئ ومعايير المحاسبة المعتمدة وما يرتبط بها من اعمال وفقا لاحكام هذا القانون .\nالتدقيق:فحص الحسابات والبيانات المالية لابداء الرأي فيها .\nالمهنة:مهنة المحاسبة القانونية بفرعيها المحاسبة والتدقيق .\nالمحاسب القانوني:الشخص الطبيعي المجاز لمزاولة المهنة وفقا لاحكام هذا القانون والانظمة والتعليمات الصادرة بمقتضاه .\nاجازة المزاولة:اجازة مزاولة المهنة التي تمنح للمحاسب القانوني وفقا لاحكام هذا القانون .","title":"التعريفات","memo":"⭐ الوزير: وزير الصناعة والتجارة\n⭐ المجلس: مجلس إدارة الجمعية / الرئيس: رئيس المجلس\n⭐ التدقيق: فحص الحسابات والبيانات المالية لإبداء الرأي فيها\n⭐ المهنة بفرعيها المحاسبة والتدقيق / المحاسب القانوني: شخص طبيعي مجاز","qs":[{"q":"يقصد بالوزير في قانون تنظيم مهنة المحاسبة القانونية:","o":["وزير الصناعة والتجارة","وزير المالية","وزير العدل","وزير الاقتصاد الوطني"],"a":0},{"q":"عرّف القانون التدقيق بأنه:","o":["فحص الحسابات والبيانات المالية لإبداء الرأي فيها","تطبيق قواعد ومبادئ ومعايير المحاسبة المعتمدة","إعداد البيانات المالية الختامية وفق المعايير المعتمدة","التفتيش على مكاتب المحاسبين القانونيين المزاولين"],"a":0},{"q":"المحاسب القانوني وفق تعريف القانون هو:","o":["الشخص الطبيعي المجاز لمزاولة المهنة","الشخص الطبيعي أو الاعتباري المجاز لمزاولة المهنة","الشركة المدنية المسجلة لدى الجمعية","كل من يحمل شهادة جامعية تخصص محاسبة"],"a":0},{"q":"يقصد بـ (الرئيس) في هذا القانون:","o":["رئيس مجلس إدارة الجمعية","رئيس الهيئة العليا","رئيس لجنة الترخيص","رئيس الهيئة العامة للجمعية"],"a":0}]},{"n":"3","chapter":"","notes":[],"source":"يهدف هذا القانون الى ما يلي :-\nأ-تنظيم مزاولة المهنة والارتقاء بها .\nب-ضمان الالتزام بمعايير المحاسبة ومعايير تدقيق الحسابات المعتمدة بما يساهم في حماية الاقتصاد الوطني .\nج-الارتقاء بالمستوى العلمي والمهني للمحاسبين القانونيين .\nد-تأكيد الالتزام بقواعد سلوك المهنة وآدابها .\nهـ-تعزيز دور المحاسب القانوني وحيدته واستقلاليته .","title":"أهداف القانون","memo":"⭐ تنظيم مزاولة المهنة والارتقاء بها\n⭐ ضمان الالتزام بمعايير المحاسبة والتدقيق المعتمدة لحماية الاقتصاد الوطني\n⭐ الارتقاء بالمستوى العلمي والمهني وتأكيد قواعد السلوك\n⭐ تعزيز دور المحاسب القانوني وحيدته واستقلاليته","qs":[{"q":"جميع ما يلي من أهداف قانون تنظيم مهنة المحاسبة القانونية باستثناء:","o":["تحديد أتعاب المحاسبين القانونيين وحدها الأدنى","تنظيم مزاولة المهنة والارتقاء بها","تأكيد الالتزام بقواعد سلوك المهنة وآدابها","تعزيز دور المحاسب القانوني وحيدته واستقلاليته"],"a":0},{"q":"يهدف القانون إلى ضمان الالتزام بمعايير المحاسبة ومعايير تدقيق الحسابات المعتمدة بما يساهم في:","o":["حماية الاقتصاد الوطني","زيادة الإيرادات الضريبية","جذب الاستثمار الأجنبي","تخفيض كلفة التدقيق على الشركات"],"a":0}]},{"n":"4","chapter":"الهيئة العليا","notes":[],"source":"أ- تشكل هيئة عليا للمهنة برئاسة الوزير وعضوية كل من :-\n١-وزير الماليةنائبا للرئيس\n٢-محافظ البنك المركزي الاردني .\n٣-رئيس ديوان المحاسبة .\n٤-رئيس مجلس مفوضي هيئة الاوراق المالية .\n٥-مدير عام هيئة التأمين .\n٦-مراقب عام الشركات .\n٧-الرئيس .\n٨-شخص من ذوي الخبرة والاختصاص في المحاسبة من القطاع الخاص يعينه مجلس الوزراء بناء على تنسيب الوزير .\n٩-عضو هيئة تدريس من أي جامعة تخصص محاسبة يعينه مجلس الوزراء بناء على تنسيب الوزير المستند إلى توصية رئيس الجامعة .\n١٠-ثلاثة محاسبين قانونيين يسميهم المجلس .\nب-تكون مدة العضوية للاعضاء المنصوص عليهم في البنود (٨) و (٩) و (١٠) من الفقرة (أ) من هذه المادة سنتين قابلة للتجديد مرة واحدة ويجوز تغيير أي منهم بتعيين بديل له للمدة المتبقية من عضويته وذلك بذات الطريقة التي عين بها .","title":"تشكيل الهيئة العليا للمهنة","memo":"⭐ برئاسة وزير الصناعة والتجارة، ووزير المالية نائباً للرئيس\n⭐ تضم: محافظ البنك المركزي، رئيس ديوان المحاسبة، رئيس مفوضي هيئة الأوراق المالية، مدير هيئة التأمين، مراقب عام الشركات، رئيس الجمعية\n⭐ خبير من القطاع الخاص + عضو هيئة تدريس (يعينهما مجلس الوزراء بتنسيب الوزير) + ٣ محاسبين قانونيين يسميهم المجلس\n⭐ مدة عضوية البنود (٨،٩،١٠): سنتان قابلة للتجديد مرة واحدة","qs":[{"q":"يتولى نيابة رئاسة الهيئة العليا للمهنة:","o":["وزير المالية","محافظ البنك المركزي الأردني","رئيس ديوان المحاسبة","مراقب عام الشركات"],"a":0},{"q":"مدة عضوية المحاسبين القانونيين الثلاثة في الهيئة العليا:","o":["سنتان قابلة للتجديد مرة واحدة","ثلاث سنوات قابلة للتجديد مرة واحدة","سنتان قابلة للتجديد دون حد","أربع سنوات غير قابلة للتجديد"],"a":0},{"q":"يسمّي المحاسبين القانونيين الثلاثة الأعضاء في الهيئة العليا:","o":["مجلس إدارة الجمعية","الهيئة العامة للجمعية","مجلس الوزراء بناءً على تنسيب الوزير","الوزير"],"a":0},{"q":"أي مما يلي ليس عضواً في الهيئة العليا للمهنة بحكم منصبه؟","o":["مدير عام دائرة ضريبة الدخل والمبيعات","مدير عام هيئة التأمين","رئيس مجلس مفوضي هيئة الأوراق المالية","مراقب عام الشركات"],"a":0}]},{"n":"5","chapter":"الهيئة العليا","notes":[],"source":"تتولى الهيئة العليا المهام والصلاحيات التالية :-\nأ-اعتماد معايير المحاسبة ومعايير تدقيق الحسابات الواجبة التطبيق بناء على تنسيب المجلس .\nب-تشكيل لجنة ترخيص المهنة ووضع التعليمات اللازمة لتنظيم عملها وتحديد صلاحياتها وكيفية اجراء الامتحانات وسائر الامور المتعلقة بها .\nج-المصادقة على منح اجازة المزاولة بناء على تنسيب لجنة الترخيص والغاء هذه الاجازة بناء على تنسيب المجلس .\nد-النظر في الاعتراضات المقدمة على قرارات المجلس .\nهـ-تشكيل اللجان اللازمة لمساعدة الهيئة العليا على القيام بمهامها وتحديد صلاحياتها .\nو-اصدار التعليمات المتعلقة بتنظيم عملها والتعليمات اللازمة لتنفيذ احكام هذا القانون والانظمة الصادرة بمقتضاه .\nز-اعداد مشروعات التشريعات المتعلقة بالمهنة بالتعاون والتنسيق مع المجلس .\nح-اعتماد المعاهد المهنية للمحاسبين القانونيين او ما يماثلها .","title":"مهام الهيئة العليا وصلاحياتها","memo":"⭐ اعتماد معايير المحاسبة والتدقيق بتنسيب المجلس\n⭐ تشكيل لجنة ترخيص المهنة، والمصادقة على منح الإجازة بتنسيب لجنة الترخيص وإلغائها بتنسيب المجلس\n⭐ النظر في الاعتراضات على قرارات المجلس\n⭐ اعتماد المعاهد المهنية للمحاسبين القانونيين","qs":[{"q":"تعتمد الهيئة العليا معايير المحاسبة ومعايير تدقيق الحسابات الواجبة التطبيق بناءً على تنسيب:","o":["المجلس","لجنة الترخيص","الوزير","الهيئة العامة للجمعية"],"a":0},{"q":"تصادق الهيئة العليا على إلغاء إجازة المزاولة بناءً على تنسيب:","o":["المجلس","لجنة الترخيص","اللجنة التأديبية مباشرة","الوزير"],"a":0},{"q":"الاعتراضات المقدمة على قرارات مجلس إدارة الجمعية تنظر فيها:","o":["الهيئة العليا","الهيئة العامة للجمعية","محكمة العدل العليا ابتداءً","لجنة الترخيص"],"a":0}]},{"n":"6","chapter":"الهيئة العليا","notes":[],"source":"أ- تجتمع الهيئة العليا بدعوة من رئيسها او نائبه عند غيابه مرة على الاقل كل ثلاثة اشهر ، ويتكون النصاب القانوني لاجتماعاتها بحضور ما لايقل عن ثلثي اعضائها على ان يكون من بينهم الرئيس او نائبه وتتخذ قراراتها بأكثرية اصوات اعضائها على الاقل .\nب-يختار الوزير امين سر للهيئة العليا يتولى تنظيم اجتماعاتها وتدوين محاضرها وحفظ قيودها وسجلاتها ومتابعة تنفيذ قراراتها .","title":"اجتماعات الهيئة العليا","memo":"⭐ تجتمع مرة على الأقل كل ثلاثة أشهر بدعوة من رئيسها أو نائبه\n⭐ النصاب: ثلثا الأعضاء على أن يكون بينهم الرئيس أو نائبه\n⭐ القرارات بأكثرية أصوات أعضائها\n⭐ يختار الوزير أمين سر الهيئة العليا","qs":[{"q":"تجتمع الهيئة العليا مرة على الأقل كل:","o":["ثلاثة أشهر","شهر","ستة أشهر","سنة"],"a":0},{"q":"يكتمل النصاب القانوني لاجتماعات الهيئة العليا بحضور:","o":["ثلثي أعضائها على الأقل بينهم الرئيس أو نائبه","أغلبية أعضائها بينهم الرئيس أو نائبه","نصف أعضائها على الأقل","ثلاثة أرباع أعضائها"],"a":0},{"q":"يختار أمين سر الهيئة العليا:","o":["الوزير","رئيس الجمعية","الهيئة العليا بالانتخاب من بين أعضائها","مجلس الوزراء"],"a":0}]},{"n":"7","chapter":"الجمعية","notes":[],"source":"أ- تنشأ جمعية تسمى ( جمعية المحاسبين القانونيين الأردنيين ) تتمتع بشخصية اعتبارية ذات استقلال مالي واداري ولها بهذه الصفة تملك الاموال المنقولة وغير المنقولة والقيام بجميع التصرفات القانونية اللازمة لتحقيق اهدافها بما في ذلك ابرام العقود ولها حق التقاضي وينوب عنها في الاجراءات القضائية اي محام توكله لهذه الغاية .\nب-يمثل الرئيس الجمعية امام الجهات الرسمية واي جهة اخرى .\nج-يكون مركز الجمعية الرئيسي في عمان ولها انشاء فروع او فتح مكاتب في المملكة .","title":"إنشاء الجمعية وشخصيتها","memo":"⭐ جمعية المحاسبين القانونيين الأردنيين: شخصية اعتبارية باستقلال مالي وإداري\n⭐ ينوب عنها في الإجراءات القضائية أي محامٍ توكله\n⭐ يمثلها الرئيس أمام الجهات الرسمية\n⭐ مركزها الرئيسي عمّان ولها فروع ومكاتب في المملكة","qs":[{"q":"يمثل جمعية المحاسبين القانونيين الأردنيين أمام الجهات الرسمية:","o":["رئيس المجلس","الوزير","أمين سر المجلس","رئيس الهيئة العليا"],"a":0},{"q":"ينوب عن الجمعية في الإجراءات القضائية:","o":["أي محامٍ توكله لهذه الغاية","المحامي العام المدني","رئيس المجلس شخصياً","النائب العام"],"a":0},{"q":"يكون المركز الرئيسي للجمعية في:","o":["عمّان","العقبة","إربد","أي مدينة يحددها المجلس"],"a":0}]},{"n":"8","chapter":"الجمعية","notes":[],"source":"تهدف الجمعية الى مايلي :-\nأ-رعاية مصالح الاعضاء والحفاظ على تقاليد المهنة وشرفها .\nب-تشجيع البحث العلمي والمهني في مجالات المهنة المختلفة .\nج-المساهمة في تخطيط وتطوير برامج التدريب لرفع كفاءة العاملين في المهنة .\nد-التعاون والتنسيق مع الجمعيات والهيئات المهنية والعلمية المحلية والعربية والدولية .","title":"أهداف الجمعية","memo":"⭐ رعاية مصالح الأعضاء والحفاظ على تقاليد المهنة وشرفها\n⭐ تشجيع البحث العلمي والمهني\n⭐ المساهمة في تخطيط برامج التدريب\n⭐ التعاون مع الجمعيات المحلية والعربية والدولية","qs":[{"q":"جميع ما يلي من أهداف الجمعية باستثناء:","o":["اعتماد معايير المحاسبة ومعايير تدقيق الحسابات","رعاية مصالح الأعضاء والحفاظ على تقاليد المهنة وشرفها","تشجيع البحث العلمي والمهني في مجالات المهنة","المساهمة في تخطيط وتطوير برامج التدريب"],"a":0},{"q":"من أهداف الجمعية التعاون والتنسيق مع الجمعيات والهيئات المهنية والعلمية:","o":["المحلية والعربية والدولية","المحلية فقط","العربية فقط","الدولية المعتمدة من الهيئة العليا فقط"],"a":0}]},{"n":"9","chapter":"الجمعية","notes":[],"source":"تتولى الجمعية ، في سبيل تحقيق اهدافها ، المهام والصلاحيات التالية :-\nأ-نشر المعلومات المتعلقة بالمهنة بين المحاسبين القانونيين واصدار الكتب والمجلات والنشرات الدورية المهنية والعلمية وتبادلها وعقد المؤتمرات والاجتماعات والندوات والدورات التدريبية .\nب-التعاون في مجال المهنة مع الجامعات والمؤسسات التعليمية .\nج-توثيق العلاقات المهنية والاجتماعية بين مزاولي المهنة محليا وعربيا ودوليا .\nد-الانضمام الى عضوية الهيئات العربية والدولية ذات العلاقة بالمهنة اذا رأت ذلك مناسبا .\nهـ-اقتراح تطوير التشريعات ذات العلاقة بالمهنة .\nو-تدريب المحاسبين القانونيين لتطبيق معايير المحاسبة ومعايير تدقيق الحسابات .","title":"مهام الجمعية وصلاحياتها","memo":"⭐ نشر المعلومات وإصدار المجلات وعقد المؤتمرات والدورات\n⭐ الانضمام للهيئات العربية والدولية إذا رأت ذلك مناسباً\n⭐ اقتراح تطوير التشريعات\n⭐ تدريب المحاسبين على تطبيق معايير المحاسبة والتدقيق","qs":[{"q":"أي مما يلي ليس من مهام الجمعية وفق المادة (٩)؟","o":["المصادقة على منح إجازة المزاولة","اقتراح تطوير التشريعات ذات العلاقة بالمهنة","تدريب المحاسبين القانونيين لتطبيق معايير المحاسبة والتدقيق","التعاون في مجال المهنة مع الجامعات والمؤسسات التعليمية"],"a":0},{"q":"تنضم الجمعية إلى عضوية الهيئات العربية والدولية ذات العلاقة بالمهنة:","o":["إذا رأت ذلك مناسباً","بموافقة مجلس الوزراء","بقرار من الهيئة العليا","بموافقة الوزير"],"a":0}]},{"n":"10","chapter":"الهيئة العامة للجمعية","notes":[],"source":"تتألف الهيئة العامة للجمعية من جميع المحاسبين القانونيين المزاولين المسددين للالتزامات المالية السنوية المترتبة عليهم قبل ثلاثين يوما على الاقل من التاريخ المقرر لانعقادها .","title":"تكوين الهيئة العامة للجمعية","memo":"⭐ تتألف من جميع المحاسبين القانونيين المزاولين\n⭐ المسددين لالتزاماتهم المالية السنوية قبل ٣٠ يوماً على الأقل من موعد الانعقاد","qs":[{"q":"تتألف الهيئة العامة للجمعية من جميع المحاسبين القانونيين المزاولين المسددين لالتزاماتهم المالية السنوية قبل موعد انعقادها بـ:","o":["ثلاثين يوماً على الأقل","واحد وعشرين يوماً على الأقل","سبعة أيام على الأقل","ستين يوماً على الأقل"],"a":0},{"q":"حالة عملية: محاسب قانوني غير مزاول سدد التزاماته المالية قبل شهرين من موعد الاجتماع، فإنه:","o":["لا يكون عضواً في الهيئة العامة لأنه غير مزاول","يكون عضواً لأنه سدد التزاماته في الموعد","يكون عضواً بشرط موافقة المجلس","يكون عضواً دون حق التصويت"],"a":0}]},{"n":"11","chapter":"الهيئة العامة للجمعية","notes":[],"source":"يتم تبليغ الدعوة لاجتماعات الهيئة العامة بارسالها بالبريد المسجل قبل واحد وعشرين يوما على الاقل من موعد الاجتماع وبالنشر في صحيفتين يوميتين محليتين ولمرة واحدة قبل سبعة ايام من موعد الاجتماع ويجوز تبليغ الدعوة بالوسائل الحديثة بما في ذلك ( الفاكس ) والبريد الالكتروني على ان تتضمن الدعوة جدول الاعمال .","title":"تبليغ الدعوة لاجتماعات الهيئة العامة","memo":"⭐ بالبريد المسجل قبل ٢١ يوماً على الأقل\n⭐ وبالنشر في صحيفتين يوميتين محليتين مرة واحدة قبل ٧ أيام\n⭐ يجوز بالوسائل الحديثة (الفاكس والبريد الإلكتروني)\n⭐ يجب أن تتضمن الدعوة جدول الأعمال","qs":[{"q":"ترسل الدعوة لاجتماعات الهيئة العامة بالبريد المسجل قبل موعد الاجتماع بـ:","o":["واحد وعشرين يوماً على الأقل","ثلاثين يوماً على الأقل","سبعة أيام على الأقل","أربعة عشر يوماً على الأقل"],"a":0},{"q":"تنشر الدعوة لاجتماع الهيئة العامة في صحيفتين يوميتين محليتين:","o":["لمرة واحدة قبل سبعة أيام من موعد الاجتماع","لمرتين قبل سبعة أيام من موعد الاجتماع","لمرة واحدة قبل واحد وعشرين يوماً من موعد الاجتماع","لمرة واحدة قبل ثلاثة أيام من موعد الاجتماع"],"a":0},{"q":"يشترط في الدعوة لاجتماع الهيئة العامة أن تتضمن:","o":["جدول الأعمال","أسماء المرشحين لعضوية المجلس","البيانات المالية المدققة","تقرير مدقق الحسابات"],"a":0}]},{"n":"12","chapter":"الهيئة العامة للجمعية","notes":[],"source":"أ- تعقد الهيئة العامة اجتماعا عاديا خلال مدة لا تتجاوز ثلاثة اشهر من تاريخ انتهاء السنة المالية للجمعية في المكان والزمان اللذين يحددهما المجلس .\nب-يرأس الرئيس او نائبه عند غيابه اجتماعات الهيئة العامة ، وفي حال غيابهما معا تنتخب الهيئة العامة رئيسا للاجتماع .\nج-على الرغم مما ورد في المادة (١٠) من هذا القانون ، يجوز للمحاسبين المتدربين حضور اجتماعات الهيئة العامة دون ان يكون لهم حق التصويت .","title":"الاجتماع العادي للهيئة العامة","memo":"⭐ يعقد خلال مدة لا تتجاوز ٣ أشهر من انتهاء السنة المالية للجمعية\n⭐ المكان والزمان يحددهما المجلس\n⭐ يرأسه الرئيس أو نائبه، وعند غيابهما تنتخب الهيئة العامة رئيساً للاجتماع\n⭐ يجوز للمتدربين الحضور دون حق التصويت","qs":[{"q":"تعقد الهيئة العامة اجتماعها العادي خلال مدة لا تتجاوز:","o":["ثلاثة أشهر من تاريخ انتهاء السنة المالية للجمعية","شهرين من تاريخ انتهاء السنة المالية للجمعية","ستة أشهر من تاريخ انتهاء السنة المالية للجمعية","أربعة أشهر من تاريخ انتهاء السنة المالية للجمعية"],"a":0},{"q":"في حال غياب الرئيس ونائبه معاً عن اجتماع الهيئة العامة:","o":["تنتخب الهيئة العامة رئيساً للاجتماع","يرأس الاجتماع أمين السر","يرأس الاجتماع أكبر الأعضاء سناً","يؤجل الاجتماع لمدة سبعة أيام"],"a":0},{"q":"يجوز للمحاسبين المتدربين حضور اجتماعات الهيئة العامة:","o":["دون أن يكون لهم حق التصويت","مع حق التصويت","بموافقة المجلس ومع حق التصويت","في الاجتماعات غير العادية فقط"],"a":0}]},{"n":"13","chapter":"الهيئة العامة للجمعية","notes":[],"source":"تتولى الهيئة العامة في اجتماعها العادي المهام والصلاحيات التالية :-\nأ-مناقشة التقرير السنوي للمجلس واقراره .\nب-التصديق على البيانات الختامية للجمعية المقدمة من المجلس .\nج-مناقشة الموازنة التقديرية للجمعية واقرارها .\nد-اختيار محاسب قانوني لتدقيق حسابات الجمعية على ان لا يكون من اعضاء المجلس او أي من اللجان المشكلة بمقتضى احكام هذا القانون او الانظمة الصادرة بمقتضاه او شريكا في شركة مع أي من اعضاء المجلس .\nهـ-انتخاب رئيس المجلس واعضائه .\nو-الموافقة على مشروعات التشريعات المتعلقة بعمل الجمعية والمقترحة من المجلس .\nز-أي امور اخرى تتعلق بالمهنة يتم اقتراحها في اجتماع الهيئة العامة وتوافق على ادراجها في جدول الاعمال .","title":"مهام الهيئة العامة في اجتماعها العادي","memo":"⭐ مناقشة التقرير السنوي وإقراره، والتصديق على البيانات الختامية، وإقرار الموازنة التقديرية\n⭐ اختيار مدقق حسابات الجمعية: ليس من أعضاء المجلس أو اللجان أو شريكاً لأي عضو مجلس\n⭐ انتخاب رئيس المجلس وأعضائه\n⭐ الموافقة على مشروعات التشريعات المقترحة من المجلس","qs":[{"q":"يختار المحاسب القانوني لتدقيق حسابات الجمعية:","o":["الهيئة العامة","المجلس","الهيئة العليا","الوزير"],"a":0},{"q":"أي مما يلي يجوز اختياره لتدقيق حسابات الجمعية؟","o":["محاسب قانوني ليس عضواً في المجلس أو أي من اللجان ولا شريكاً لأي من أعضاء المجلس","عضو في اللجنة التأديبية","شريك في شركة مع أحد أعضاء المجلس","أمين صندوق المجلس"],"a":0},{"q":"ينتخب رئيس مجلس إدارة الجمعية من قبل:","o":["الهيئة العامة","أعضاء المجلس من بينهم","الهيئة العليا","الوزير"],"a":0}]},{"n":"14","chapter":"الهيئة العامة للجمعية","notes":[],"source":"أ- يكون النصاب القانوني لاجتماع الهيئة العامة العادي بحضور ما يزيد على نصف المحاسبين القانونيين المزاولين المسددين للالتزامات المالية السنوية المترتبة عليهم ، واذا لم يكتمل النصاب خلال ساعة واحدة من الوقت المحدد للاجتماع يؤجل لمدة لا تزيد على سبعة ايام من التاريخ المقرر للاجتماع الاول ويكتفى بنشر الدعوة في صحيفتين يوميتين محليتين ويكون النصاب في الاجتماع الثاني قانونيا مهما كان عدد الحضور .\nب-يكون التصويت في الهيئة العامة علنيا باستثناء الانتخابات الدورية لاعضاء المجلس فتكون سرية ، الا انه يجوز ان تتخذ القرارات بطريقة الاقتراع السري اذا قرر اكثر من ربع المحاسبين القانونيين الحاضرين ذلك .\nج-تتخذ قرارات الهيئة العامة في اجتماعها العادي باكثرية اصوات المحاسبين القانونيين الحاضرين .","title":"نصاب وقرارات الاجتماع العادي","memo":"⭐ النصاب: أكثر من نصف المزاولين المسددين\n⭐ إن لم يكتمل خلال ساعة يؤجل لمدة لا تزيد على ٧ أيام، والاجتماع الثاني قانوني مهما كان العدد\n⭐ التصويت علني إلا انتخابات المجلس سرية، ويجوز السري إذا قرر أكثر من ربع الحاضرين\n⭐ القرارات بأكثرية أصوات الحاضرين","qs":[{"q":"إذا لم يكتمل نصاب الاجتماع العادي للهيئة العامة خلال ساعة من الوقت المحدد:","o":["يؤجل لمدة لا تزيد على سبعة أيام ويكون النصاب في الثاني قانونياً مهما كان عدد الحضور","يعتبر الاجتماع ملغى","يؤجل لمدة لا تزيد على واحد وعشرين يوماً ويشترط حضور ثلث الأعضاء","يعقد الاجتماع بمن حضر في اليوم ذاته"],"a":0},{"q":"يجوز اتخاذ قرارات الهيئة العامة بطريقة الاقتراع السري إذا قرر ذلك:","o":["أكثر من ربع المحاسبين القانونيين الحاضرين","أكثر من نصف المحاسبين القانونيين الحاضرين","ثلثا المحاسبين القانونيين الحاضرين","رئيس الاجتماع"],"a":0},{"q":"يكون التصويت سرياً وجوباً في الهيئة العامة في حالة:","o":["الانتخابات الدورية لأعضاء المجلس","إقرار الموازنة التقديرية","التصديق على البيانات الختامية","اختيار مدقق حسابات الجمعية"],"a":0}]},{"n":"15","chapter":"الهيئة العامة للجمعية","notes":[],"source":"أ- يتم دعوة الهيئة العامة الى اجتماع غير عادي يقتصر البحث فيه على الامور المحددة في جدول الاعمال بما في ذلك تعديل أي من الانظمة الصادرة بمقتضى احكام هذا القانون او اقالة الرئيس او نائبه او أي من اعضاء المجلس في أي من الحالتين التاليتين :-\n١-بناء على قرار من المجلس .\n٢-بناء على طلب يقدمه للمجلس ما لا يقل عن (٢٠٪) من المحاسبين القانونيين المزاولين المسددين للالتزامات المالية المترتبة عليهم قبل ثلاثين يوما من تاريخ تسلم الطلب متضمنا جدول اعمال الاجتماع .\nب-يكون النصاب القانوني لاجتماع الهيئة العامة غير العادي بحضور ما يزيد على نصف المحاسبين القانونيين المزاولين المسددين للالتزامات المالية المترتبة عليهم ، واذا لم يكتمل النصاب خلال ساعة واحدة من الوقت المحدد للاجتماع يعتبر الاجتماع ملغى .\nج-تطبق احكام الفقرتين (ب) و (ج) من المادة (١٢) واحكام الفقرة (ب) من المادة (١٤) من هذا القانون على اجتماع الهيئة العامة غير العادي .\nد-تتخذ القرارات في اجتماع الهيئة العامة غير العادي باكثرية لا تقل عن ثلثي اصوات المحاسبين القانونيين الحاضرين.","title":"الاجتماع غير العادي للهيئة العامة","memo":"⭐ يدعى إليه بقرار من المجلس أو بطلب لا يقل عن ٢٠٪ من المزاولين المسددين\n⭐ يقتصر على جدول الأعمال، ومنه تعديل الأنظمة أو إقالة الرئيس أو نائبه أو أعضاء المجلس\n⭐ النصاب: أكثر من النصف، وإن لم يكتمل خلال ساعة يعتبر الاجتماع ملغى\n⭐ القرارات بأكثرية لا تقل عن ثلثي أصوات الحاضرين","qs":[{"q":"يجوز دعوة الهيئة العامة لاجتماع غير عادي بناءً على طلب يقدم للمجلس من:","o":["ما لا يقل عن (٢٠٪) من المحاسبين القانونيين المزاولين المسددين","ما لا يقل عن (٢٥٪) من المحاسبين القانونيين المزاولين المسددين","ما لا يقل عن (١٠٪) من المحاسبين القانونيين المزاولين المسددين","أكثر من نصف المحاسبين القانونيين المزاولين المسددين"],"a":0},{"q":"إذا لم يكتمل نصاب اجتماع الهيئة العامة غير العادي خلال ساعة من الوقت المحدد:","o":["يعتبر الاجتماع ملغى","يؤجل لمدة لا تزيد على سبعة أيام","يكون النصاب قانونياً مهما كان عدد الحضور","يؤجل إلى موعد يحدده الوزير"],"a":0},{"q":"تتخذ القرارات في اجتماع الهيئة العامة غير العادي بأكثرية لا تقل عن:","o":["ثلثي أصوات الحاضرين","أكثرية أصوات الحاضرين","ثلاثة أرباع أصوات الحاضرين","نصف أصوات الأعضاء المسددين"],"a":0},{"q":"حالة عملية: يرغب عدد من المحاسبين القانونيين في إقالة نائب رئيس المجلس، فإن ذلك يتم من خلال:","o":["اجتماع غير عادي للهيئة العامة","الاجتماع العادي السنوي فقط","قرار من الهيئة العليا","قرار من الوزير"],"a":0}]},{"n":"16","chapter":"مجلس ادارة الجمعية","notes":[],"source":"أ- يتألف مجلس ادارة الجمعية من رئيس وثمانية اعضاء تنتخبهم الهيئة العامة لمدة ثلاث سنوات وفقا لاحكام النظام الداخلي للجمعية .\nب-ينتخب المجلس من بين اعضائه في اول اجتماع يعقده نائبا للرئيس وامينا للسر وامينا للصندوق .\nج-يجوز اعادة انتخاب الرئيس او نائبه او عضو المجلس لدورة ثانية ولا يحق لاي منهم ترشيح نفسه للمركز ذاته الا بعد انقضاء دورة واحدة على الاقل على انتهاء مدة دورته الاخيرة .","title":"تأليف مجلس إدارة الجمعية","memo":"⭐ رئيس و٨ أعضاء تنتخبهم الهيئة العامة لمدة ٣ سنوات\n⭐ ينتخب المجلس من بين أعضائه في أول اجتماع: نائب الرئيس وأمين السر وأمين الصندوق\n⭐ يجوز إعادة الانتخاب لدورة ثانية فقط، ثم لا يترشح للمركز ذاته إلا بعد انقضاء دورة واحدة على الأقل","qs":[{"q":"يتألف مجلس إدارة الجمعية من:","o":["رئيس وثمانية أعضاء","رئيس وستة أعضاء","رئيس وعشرة أعضاء","رئيس وسبعة أعضاء"],"a":0},{"q":"مدة دورة مجلس إدارة الجمعية:","o":["ثلاث سنوات","سنتان","أربع سنوات","سنة واحدة"],"a":0},{"q":"حالة عملية: رئيس مجلس انتخب لدورتين متتاليتين، فإنه يحق له الترشح للمركز ذاته:","o":["بعد انقضاء دورة واحدة على الأقل على انتهاء دورته الأخيرة","مباشرة لدورة ثالثة","بعد انقضاء دورتين على الأقل","بموافقة الهيئة العليا"],"a":0}]},{"n":"17","chapter":"مجلس ادارة الجمعية","notes":[],"source":"يتولى المجلس المهام والصلاحيات التالية :-\nأ-ادارة شؤون الجمعية الادارية والمالية .\nب-ترسيخ قواعد السلوك المهني .\nج-التنسيب للهيئة العليا باعتماد معايير المحاسبة ومعايير تدقيق الحسابات .\nد-التعاون مع الهيئة العليا في اعداد مشروعات التشريعات ، واقتراح مشروعات الانظمة المتعلقة بالمهنة .\nهـ-التنسيب للهيئة العليا بالغاء اجازة المزاولة .\nو-دعوة الهيئة العامة للاجتماع وتنفيذ قراراتها .\nز-تشكيل اللجان اللازمة لمساعدته على قيامه بمهامه بما في ذلك لجنة التفتيش على مكاتب المحاسبين القانونيين المزاولين .\nح-شؤون التقاعد والتعاون والتأمين الصحي والاسكان وتحصيل عوائدها وذلك بموجب تعليمات يضعها المجلس وتوافق عليها الهيئة العامة وتصادق عليها الهيئة العليا على ان تتضمن هذه التعليمات حق المجلس في تفويض هذه الصلاحية الى لجنة ادارة أي صندوق او التعاقد مع أي جهة اخرى لهذه الغاية .\nط-النظر في النزاعات بين المحاسبين القانونيين المتعلقة بمزاولة المهنة وبين المحاسبين القانونيين وعملائهم ، واقرار التسويات المناسبة بشأن هذه النزاعات .\nي-وضع اسس تعيين موظفي الجمعية وتحديد رواتبهم وشروط استخدامهم وانهاء خدماتهم .\nك-أي امور اخرى ذات علاقة بعمل الجمعية .","title":"مهام المجلس وصلاحياته","memo":"⭐ إدارة شؤون الجمعية الإدارية والمالية وترسيخ قواعد السلوك\n⭐ التنسيب للهيئة العليا باعتماد المعايير وبإلغاء إجازة المزاولة\n⭐ تشكيل اللجان ومنها لجنة التفتيش على مكاتب المزاولين\n⭐ النظر في النزاعات بين المحاسبين وبينهم وبين عملائهم وإقرار التسويات","qs":[{"q":"تعليمات شؤون التقاعد والتأمين الصحي والإسكان يضعها المجلس وتوافق عليها الهيئة العامة وتصادق عليها:","o":["الهيئة العليا","الوزير","مجلس الوزراء","لجنة إدارة الصندوق"],"a":0},{"q":"النزاعات بين المحاسبين القانونيين وعملائهم المتعلقة بمزاولة المهنة ينظر فيها:","o":["المجلس","الهيئة العليا","اللجنة التأديبية","الهيئة العامة"],"a":0},{"q":"لجنة التفتيش على مكاتب المحاسبين القانونيين المزاولين يشكلها:","o":["المجلس","الهيئة العليا","الوزير","الهيئة العامة"],"a":0}]},{"n":"18","chapter":"مجلس ادارة الجمعية","notes":[],"source":"يجتمع المجلس مرة على الاقل كل شهر بدعوة من رئيسه او نائبه عند غيابه او بناء على طلب خطي يتقدم به خمسة من اعضاء المجلس ، ويكون اجتماعه قانونيا بحضور ما لا يقل عن اغلبية اعضائه على ان يكون الرئيس او نائبه من بينهم ويتخذ قراراته باغلبية اصوات اعضائه الحاضرين على الاقل وعند تساوي الاصوات يرجح الجانب الذي صوت معه رئيس الاجتماع ، ولا يجوز الامتناع عن التصويت .","title":"اجتماعات المجلس","memo":"⭐ يجتمع مرة على الأقل كل شهر بدعوة من رئيسه أو نائبه أو بطلب خطي من ٥ أعضاء\n⭐ النصاب: أغلبية الأعضاء بينهم الرئيس أو نائبه\n⭐ القرارات بأغلبية الحاضرين، وعند التساوي يرجح جانب رئيس الاجتماع\n⭐ لا يجوز الامتناع عن التصويت","qs":[{"q":"يجتمع مجلس إدارة الجمعية مرة على الأقل كل:","o":["شهر","ثلاثة أشهر","أسبوعين","شهرين"],"a":0},{"q":"يجوز دعوة المجلس للاجتماع بناءً على طلب خطي يتقدم به:","o":["خمسة من أعضاء المجلس","ثلاثة من أعضاء المجلس","أربعة من أعضاء المجلس","ثلثا أعضاء المجلس"],"a":0},{"q":"عند تساوي الأصوات في اجتماع المجلس:","o":["يرجح الجانب الذي صوت معه رئيس الاجتماع","يعاد التصويت في الجلسة التالية","يعتبر الاقتراح مرفوضاً","يحال الأمر إلى الهيئة العليا"],"a":0}]},{"n":"19","chapter":"مجلس ادارة الجمعية","notes":[],"source":"اذا انتهت مدة المجلس وتعذر على الهيئة العامة ، لاي سبب من الاسباب عقد الاجتماع لانتخاب مجلس جديد ، يستمر المجلس في عمله ، وعلى الوزير في هذه الحالة دعوة الهيئة العامة لانتخاب مجلس جديد خلال مدة لا تتجاوز ثلاثة اشهر من تاريخ انتهاء مدة المجلس قابلة للتمديد ثلاثة اشهر اخرى .","title":"استمرار المجلس بعد انتهاء مدته","memo":"⭐ إذا تعذر انتخاب مجلس جديد يستمر المجلس في عمله\n⭐ على الوزير دعوة الهيئة العامة خلال ٣ أشهر من انتهاء مدة المجلس قابلة للتمديد ٣ أشهر أخرى","qs":[{"q":"إذا انتهت مدة المجلس وتعذر على الهيئة العامة عقد اجتماع لانتخاب مجلس جديد، فإن الدعوة لانتخاب مجلس جديد تكون من:","o":["الوزير","الهيئة العليا","رئيس المجلس المنتهية مدته","مجلس الوزراء"],"a":0},{"q":"على الوزير دعوة الهيئة العامة لانتخاب مجلس جديد خلال مدة لا تتجاوز:","o":["ثلاثة أشهر من تاريخ انتهاء مدة المجلس قابلة للتمديد ثلاثة أشهر أخرى","ستة أشهر غير قابلة للتمديد","شهر قابل للتمديد شهراً آخر","سنة من تاريخ انتهاء مدة المجلس"],"a":0}]},{"n":"20","chapter":"مجلس ادارة الجمعية","notes":[],"source":"أ- تحتفظ الجمعية بالسجلات الخاصة بالمحاسبين القانونيين بما في ذلك ما يلي :-\n١-السجل العام .\n٢-سجل المزاولين .\n٣-سجل غير المزاولين .\n٤-سجل المتدربين .\nب-يحدد النظام الداخلي للجمعية المعلومات والوثائق التي يجب ان تدون او تحفظ في كل سجل .","title":"سجلات الجمعية","memo":"⭐ أربعة سجلات: العام، المزاولين، غير المزاولين، المتدربين\n⭐ يحدد النظام الداخلي للجمعية المعلومات والوثائق في كل سجل","qs":[{"q":"أي مما يلي ليس من السجلات التي تحتفظ بها الجمعية وفق المادة (٢٠)؟","o":["سجل الشركات المدنية للمحاسبين","السجل العام","سجل غير المزاولين","سجل المتدربين"],"a":0},{"q":"تحدد المعلومات والوثائق التي يجب أن تدون في كل سجل من سجلات الجمعية بموجب:","o":["النظام الداخلي للجمعية","تعليمات تصدرها الهيئة العليا","قرار من الوزير","نظام مزاولة مهنة المحاسبة القانونية"],"a":0}]},{"n":"21","chapter":"مزاولة المهنة","notes":[],"source":"يحظر على أي شخص غير حاصل على اجازة المزاولة وغير مسجل في سجل المزاولين ما يلي :-\nأ-مزاولة اعمال التدقيق .\nب-العمل في أي وظيفة رئيسية تتعلق بأعمال المحاسبة لدى أي من الجهات المنصوص عليها في الفقرة (ب) من المادة (٣٠) من هذا القانون بعد مرور المدة المنصوص عليها في الفقرة (أ) من المادة (٣١) من هذا القانون والتعليمات الصادرة بمقتضاه .","title":"المحظور على غير المجاز","memo":"⭐ يحظر على غير الحاصل على الإجازة وغير المسجل في سجل المزاولين: مزاولة أعمال التدقيق\n⭐ والعمل في وظيفة رئيسية تتعلق بالمحاسبة لدى الجهات في المادة ٣٠/ب بعد مرور مدة توفيق الأوضاع","qs":[{"q":"يحظر على الشخص غير الحاصل على إجازة المزاولة وغير المسجل في سجل المزاولين:","o":["مزاولة أعمال التدقيق","العمل محاسباً متدرباً لدى محاسب قانوني","العمل في أي وظيفة محاسبية لدى أي جهة","حضور اجتماعات الهيئة العامة"],"a":0},{"q":"يشترط لمزاولة أعمال التدقيق أن يكون الشخص:","o":["حاصلاً على إجازة المزاولة ومسجلاً في سجل المزاولين","حاصلاً على شهادة جامعية تخصص محاسبة فقط","مسجلاً في سجل المتدربين","عضواً في الهيئة العامة للجمعية فقط"],"a":0}]},{"n":"22","chapter":"مزاولة المهنة","notes":[],"source":"يشترط فيمن يتقدم بطلب للحصول على اجازة المزاولة توافر الشروط التالية :-\nأ-ان يكون اردني الجنسية .\nب-ان يكون متمتعا بالاهلية المدنية الكاملة .\nج-غير محكوم عليه بجناية او بجنحة مخلة بالاخلاق او الامانة .\nد-ان يكون حاصلا على أي من المؤهلات التالية :-\n١-شهادة جامعية تخصص محاسبة .\n٢-شهادة كلية مجتمع ( الدبلوم ) تخصص محاسبة .\n٣-شهادة جامعية في أي من التخصصات ذات العلاقة بالمهنة على ان تتضمن الحد الادنى من المواد المتعلقة بالمحاسبة ، ويتم تحديد هذه الشهادات والحد الادنى المطلوب بمقتضى نظام مزاولة مهنة المحاسبة القانونية .\n٤-شهادة في المهنة من المعاهد المهنية للمحاسبين القانونيين او ما يماثلها والمعترف بها من الهيئة العليا بموجب تعليمات تصدرها لهذه الغاية اذا كان حاصلا على شهادة جامعية .\nهـ-ان يستكمل متطلبات التدريب المنصوص عليها في هذا القانون ونظام مزاولة مهنة المحاسبة القانونية الصادر بمقتضاه .\nو-ان يجتاز الامتحان الذي تجريه لجنة الترخيص بما في ذلك الامتحان بالتشريعات الاردنية ذات العلاقة بالمهنة .","title":"شروط الحصول على إجازة المزاولة","memo":"⭐ أردني الجنسية، متمتع بالأهلية المدنية الكاملة، غير محكوم بجناية أو جنحة مخلة بالأخلاق أو الأمانة\n⭐ المؤهل: شهادة جامعية أو دبلوم كلية مجتمع تخصص محاسبة، أو تخصص ذو علاقة، أو شهادة مهنية مع شهادة جامعية\n⭐ استكمال متطلبات التدريب\n⭐ اجتياز امتحان لجنة الترخيص بما فيه امتحان التشريعات الأردنية","qs":[{"q":"أي مما يلي ليس من شروط الحصول على إجازة المزاولة؟","o":["أن يكون حاصلاً على درجة الماجستير في المحاسبة","أن يكون أردني الجنسية","أن يكون متمتعاً بالأهلية المدنية الكاملة","أن يجتاز الامتحان الذي تجريه لجنة الترخيص"],"a":0},{"q":"من المؤهلات المقبولة للحصول على إجازة المزاولة:","o":["شهادة كلية مجتمع (الدبلوم) تخصص محاسبة","شهادة الثانوية العامة الفرع التجاري","دبلوم كلية مجتمع في أي تخصص","شهادة مهنية من معهد معترف به دون شهادة جامعية"],"a":0},{"q":"الجهة التي تجري امتحان الحصول على إجازة المزاولة بما فيه امتحان التشريعات الأردنية:","o":["لجنة الترخيص","الجمعية","الهيئة العامة","الوزارة"],"a":0}]},{"n":"23","chapter":"مزاولة المهنة","notes":[],"source":"أ- يقدم طلب اجازة المزاولة الى لجنة الترخيص على الانموذج المعتمد من الهيئة العليا لهذه الغاية مرفقا به الشهادات والوثائق المطلوبة وفقا لاحكام هذا القانون والانظمة الصادرة بمقتضاه .\nب-على لجنة الترخيص رفع تنسيبها بشان الطلب المنصوص عليه في الفقرة (أ) من هذه المادة والمستكمل الشروط الى الهيئة العليا خلال مدة لا تتجاوز ستين يوما من تاريخ تقديمه ، وعلى الهيئة العليا ان تصدر قرارها بشأنه في اول اجتماع تعقده .\nج-اذا وافقت الهيئة العليا على الطلب فعلى مقدمه استكمال اجراءات تسجيله محاسبا قانونيا في الجمعية خلال ستين يوما من تاريخ تبلغه قرار الموافقة والا تعتبر الموافقة ملغاة حكما .\nد-اذا رفضت الهيئة العليا الطلب يجوز لمقدمه الطعن بقرارها لدى محكمة العدل العليا خلال ثلاثين يوما من تاريخ تبلغه هذا القرار .\nهـ-لا يحول رفض الطلب دون تقديم طلب جديد اذا زالت الاسباب التي ادت الى رفضه .","title":"إجراءات طلب إجازة المزاولة","memo":"⭐ يقدم الطلب للجنة الترخيص على نموذج الهيئة العليا\n⭐ ترفع اللجنة تنسيبها خلال ٦٠ يوماً، وتقرر الهيئة العليا في أول اجتماع\n⭐ عند الموافقة يستكمل التسجيل خلال ٦٠ يوماً من التبلغ وإلا تلغى حكماً\n⭐ عند الرفض الطعن لدى محكمة العدل العليا خلال ٣٠ يوماً، ويجوز طلب جديد بزوال الأسباب","qs":[{"q":"على لجنة الترخيص رفع تنسيبها بشأن طلب إجازة المزاولة المستكمل للشروط إلى الهيئة العليا خلال مدة لا تتجاوز:","o":["ستين يوماً من تاريخ تقديمه","ثلاثين يوماً من تاريخ تقديمه","تسعين يوماً من تاريخ تقديمه","واحد وعشرين يوماً من تاريخ تقديمه"],"a":0},{"q":"حالة عملية: وافقت الهيئة العليا على طلب أحمد، ولم يستكمل إجراءات تسجيله في الجمعية خلال ستين يوماً من تبلغه القرار، فإن:","o":["الموافقة تعتبر ملغاة حكماً","المجلس يمنحه مهلة إضافية ثلاثين يوماً","الهيئة العليا تنذره خطياً","الموافقة تبقى قائمة لمدة سنة"],"a":0},{"q":"يجوز لمن رفضت الهيئة العليا طلبه الطعن بقرارها لدى محكمة العدل العليا خلال:","o":["ثلاثين يوماً من تاريخ تبلغه القرار","ستين يوماً من تاريخ تبلغه القرار","خمسة عشر يوماً من تاريخ صدور القرار","تسعين يوماً من تاريخ صدور القرار"],"a":0}]},{"n":"24","chapter":"مزاولة المهنة","notes":[],"source":"أ- يقسم مقدم الطلب بعد الموافقة على طلبه ، وقبل منحه اجازة المزاولة ، امام رئيس الهيئة العليا او من ينتدبه من اعضائها بحضور الرئيس اليمين التالية :-\n( اقسم بالله العظيم ان اقوم بواجبات مهنتي بشرف وامانة دون تحيز وان اتقيد بالقوانين والانظمة والتعليمات المعمول بها وان احافظ على اسرار المهنة وآدابها وقواعدها ) .\nب-يتم نشر القرار الصادر عن الهيئة العليا بمنح الاجازة في الجريدة الرسمية على نفقة الجمعية وتحفظ نسخة من هذه الاجازة في الملف الخاص بمقدم الطلب .","title":"اليمين ونشر قرار منح الإجازة","memo":"⭐ يقسم مقدم الطلب بعد الموافقة وقبل منح الإجازة أمام رئيس الهيئة العليا أو من ينتدبه بحضور الرئيس\n⭐ ينشر قرار منح الإجازة في الجريدة الرسمية على نفقة الجمعية","qs":[{"q":"يؤدي مقدم طلب إجازة المزاولة اليمين:","o":["بعد الموافقة على طلبه وقبل منحه الإجازة","قبل التقدم لامتحان لجنة الترخيص","بعد منحه الإجازة وتسجيله في سجل المزاولين","عند تسجيله في سجل المتدربين"],"a":0},{"q":"ينشر قرار الهيئة العليا بمنح إجازة المزاولة في الجريدة الرسمية على نفقة:","o":["الجمعية","مقدم الطلب","الوزارة","الهيئة العليا"],"a":0},{"q":"يؤدي مقدم الطلب اليمين أمام:","o":["رئيس الهيئة العليا أو من ينتدبه من أعضائها بحضور رئيس الجمعية","رئيس محكمة العدل العليا","الهيئة العامة للجمعية","رئيس لجنة الترخيص"],"a":0}]},{"n":"25","chapter":"مزاولة المهنة","notes":[],"source":"مع مراعاة مبدأ المعاملة بالمثل ، يجوز لاي شخص غير اردني التسجيل في سجل المحاسبين القانونيين لمزاولة المهنة في المملكة شريطة ان تتوافر فيه الشروط المنصوص عليها في هذا القانون والانظمة والتعليمات الصادرة بمقتضاه شريطة التقيد بتشريعات العمل والاقامة النافذة المفعول .","title":"تسجيل غير الأردني","memo":"⭐ يجوز لغير الأردني التسجيل لمزاولة المهنة مع مراعاة مبدأ المعاملة بالمثل\n⭐ بشرط توافر شروط القانون والتقيد بتشريعات العمل والإقامة","qs":[{"q":"يجوز لغير الأردني التسجيل في سجل المحاسبين القانونيين لمزاولة المهنة في المملكة مع مراعاة:","o":["مبدأ المعاملة بالمثل","موافقة مجلس الوزراء","الحصول على الإقامة الدائمة","الشراكة مع محاسب قانوني أردني"],"a":0},{"q":"يشترط في غير الأردني الراغب بمزاولة المهنة في المملكة، إضافة إلى شروط القانون:","o":["التقيد بتشريعات العمل والإقامة النافذة","الإقامة في المملكة مدة لا تقل عن سنتين","الحصول على موافقة الوزير","أن يكون حاصلاً على إجازة مزاولة من بلده فقط"],"a":0}]},{"n":"26","chapter":"مزاولة المهنة","notes":[],"source":"أ- تصدر الهيئة العليا التعليمات اللازمة لتحديد شروط تصنيف المحاسبين القانونيين وفقا لمجال مزاولتهم للمهنة على ان تتضمن هذه التعليمات من يتوجب عليه منهم التأمين ضد المسؤولية المدنية عن أي عطل وضرر يلحق بالغير نتيجة لمزاولته للمهنة .\nب-تحدد شروط واحكام التأمين المنصوص عليه في الفقرة (أ) من هذه المادة بموجب نظام يصدر لهذه الغاية بمقتضى قانون تنظيم اعمال التأمين المعمول به .","title":"تصنيف المحاسبين والتأمين ضد المسؤولية","memo":"⭐ تصدر الهيئة العليا تعليمات تصنيف المحاسبين وفق مجال مزاولتهم\n⭐ تحدد التعليمات من يلزم بالتأمين ضد المسؤولية المدنية عن الضرر بالغير\n⭐ شروط التأمين بنظام يصدر بمقتضى قانون تنظيم أعمال التأمين","qs":[{"q":"تصدر التعليمات اللازمة لتحديد شروط تصنيف المحاسبين القانونيين وفقاً لمجال مزاولتهم للمهنة عن:","o":["الهيئة العليا","المجلس","الوزير","هيئة التأمين"],"a":0},{"q":"تحدد شروط وأحكام تأمين المحاسب القانوني ضد المسؤولية المدنية بموجب:","o":["نظام يصدر بمقتضى قانون تنظيم أعمال التأمين","تعليمات يصدرها المجلس","النظام الداخلي للجمعية","قرار من الهيئة العامة"],"a":0}]},{"n":"27","chapter":"مزاولة المهنة","notes":[],"source":"أ- تحدد قواعد سلوك المهنة وآدابها بمقتضى تعليمات تصدرها الهيئة العليا بناء على تنسيب المجلس .\nب-على المحاسب القانوني الالتزام بقواعد سلوك المهنة وآدابها ويترتب عليه عند القيام بواجبات عمله ان يحافظ على اسرار المهنة تحت طائلة المسؤولية القانونية .","title":"قواعد سلوك المهنة وآدابها","memo":"⭐ تحدد قواعد السلوك بتعليمات تصدرها الهيئة العليا بتنسيب المجلس\n⭐ على المحاسب الالتزام بها والمحافظة على أسرار المهنة تحت طائلة المسؤولية القانونية","qs":[{"q":"تحدد قواعد سلوك المهنة وآدابها بمقتضى تعليمات تصدرها:","o":["الهيئة العليا بناءً على تنسيب المجلس","المجلس بناءً على تنسيب الهيئة العليا","الهيئة العامة بناءً على تنسيب المجلس","مجلس الوزراء بناءً على تنسيب الوزير"],"a":0},{"q":"إخلال المحاسب القانوني بالمحافظة على أسرار المهنة أثناء قيامه بواجبات عمله يرتب عليه:","o":["المسؤولية القانونية","إلغاء إجازته حكماً","غرامة ثلاثة دنانير عن كل يوم","وقف تدريبه"],"a":0}]},{"n":"28","chapter":"التدريب","notes":[],"source":"أ- مع مراعاة احكام المادة (٤٢) من هذا القانون ، يقدم طلب التسجيل في سجل المتدربين الى الجمعية على الانموذج المعتمد لهذه الغاية مرفقا به الوثائق التي تثبت توافر الشروط المنصوص عليها في الفقرات (أ) و (ب) و (ج) و (د) من المادة (٢٢) من هذا القانون .\nب-لا يقبل طلب التسجيل في سجل المتدربين ما لم يكن مرفقا بموافقة خطية من المحاسب القانوني الذي يرغب طالب التسجيل في التدرب لديه وتحت اشرافه وعلى مسؤوليته .","title":"التسجيل في سجل المتدربين","memo":"⭐ يقدم الطلب إلى الجمعية مع وثائق شروط المادة ٢٢ (أ،ب،ج،د)\n⭐ لا يقبل إلا بموافقة خطية من المحاسب القانوني الذي سيتدرب لديه وتحت إشرافه ومسؤوليته","qs":[{"q":"يقدم طلب التسجيل في سجل المتدربين إلى:","o":["الجمعية","لجنة الترخيص","الهيئة العليا","الوزارة"],"a":0},{"q":"لا يقبل طلب التسجيل في سجل المتدربين ما لم يكن مرفقاً به:","o":["موافقة خطية من المحاسب القانوني الذي يرغب بالتدرب لديه","شهادة اجتياز امتحان لجنة الترخيص","شهادة خبرة عملية في المحاسبة","موافقة الهيئة العليا"],"a":0},{"q":"أي من شروط المادة (٢٢) لا يلزم إثباته عند التسجيل في سجل المتدربين؟","o":["اجتياز الامتحان الذي تجريه لجنة الترخيص","الجنسية الأردنية","الأهلية المدنية الكاملة","المؤهل العلمي المطلوب"],"a":0}]},{"n":"29","chapter":"التدريب","notes":[],"source":"تحدد بمقتضى نظام مزاولة مهنة المحاسبة القانونية الاحكام المتعلقة بالتدريب ومدده واحكامه واسس تحديد راتب المتدربين وسائر الامور المتعلقة بهم .","title":"أحكام التدريب","memo":"⭐ تحدد أحكام التدريب ومدده وأسس راتب المتدربين بمقتضى نظام مزاولة مهنة المحاسبة القانونية","qs":[{"q":"تحدد الأحكام المتعلقة بالتدريب ومدده وأسس تحديد راتب المتدربين بمقتضى:","o":["نظام مزاولة مهنة المحاسبة القانونية","النظام الداخلي للجمعية","تعليمات تصدرها الهيئة العليا","قرار من المجلس"],"a":0},{"q":"حالة عملية: يرغب متدرب في معرفة مدة التدريب المطلوبة، فعليه الرجوع إلى:","o":["نظام مزاولة مهنة المحاسبة القانونية","قانون تنظيم مهنة المحاسبة القانونية مباشرة","تعليمات لجنة الترخيص","النظام الداخلي للجمعية"],"a":0}]},{"n":"30","chapter":"الجهات الملزمة بتعيين محاسب قانوني","notes":[],"source":"أ- مع مراعاة ما ورد في أي تشريع اخر ، تلتزم الجهات المبينة ادناه باختيار محاسب قانوني مسجل في سجل المحاسبين القانونيين المزاولين لغايات تدقيق حساباتها :-\n١-الشركات المساهمة العامة والمساهمة الخاصة وذات المسؤولية المحدودة والتوصية بالاسهم .\n٢-شركة التضامن والتوصية البسيطة التي يزيد رأسمالها او حجم مبيعاتها السنوية على مائة الف دينار .\n٣-المؤسسات او الشركات التي ينطبق عليها حد التسجيل وفقا لقانون الضريبة العامة على المبيعات والانظمة الصادرة بمقتضاه .\n٤-النقابات والجمعيات التي تؤسس بمقتضى التشريعات المعمول بها .\n٥-الاندية التي تحدد بموجب قرار صادر عن الهيئة العليا .\n٦-المؤسسة المسجلة وفقا لقانون منطقة العقبة الاقتصادية الخاصة واستنادا لقرار تتخذه الهيئة العليا بناء على تنسيب مجلس مفوضي منطقة العقبة الاقتصادية الخاصة .\n٧-المؤسسات والشركات المسجلة وفقا لاحكام قانون المناطق الحرة المعمول به .\nب-تلتزم الشركات المساهمة العامة والمساهمة الخاصة بتعيين محاسب قانوني مجاز في أي وظيفة رئيسية تتعلق باعمال المحاسبة ويسري هذا الالتزام على الشركات ذات المسؤولية المحدودة التي يتجاوز رأسمالها او حجم مبيعاتها السنوية مليون دينار ويتم تنفيذ احكام هذه الفقرة بما في ذلك تاريخ البدء في تطبيقها بمقتضى التعليمات التي تصدرها الهيئة العليا لهذه الغاية .\nج-على كل من تخلف عن تعيين محاسب قانوني وفقا لاحكام الفقرتين (أ) و (ب) من هذه المادة دفع غرامة الى الجمعية مقدارها ثلاثة دنانير عن كل يوم يتخلف فيه عن ذلك بعد ثلاثة اشهر من انتهاء المدة المنصوص عليها في الفقرة (أ) من المادة (٣١) من هذا القانون .","title":"الجهات الملزمة بتعيين محاسب قانوني","memo":"⭐ ملزمة بالتدقيق: المساهمة العامة والخاصة وذات المسؤولية المحدودة والتوصية بالأسهم، والتضامن والتوصية البسيطة إذا زاد رأسمالها أو مبيعاتها على ١٠٠ ألف دينار\n⭐ وكذلك: المسجلون بحد ضريبة المبيعات، النقابات والجمعيات، الأندية بقرار الهيئة العليا، مؤسسات العقبة والمناطق الحرة\n⭐ تعيين محاسب مجاز في الوظيفة المحاسبية الرئيسية: المساهمة العامة والخاصة، وذات المسؤولية المحدودة إذا تجاوز رأسمالها أو مبيعاتها مليون دينار\n⭐ الغرامة: ٣ دنانير عن كل يوم تخلف بعد ٣ أشهر من انتهاء مدة توفيق الأوضاع","qs":[{"q":"تلتزم شركة التضامن باختيار محاسب قانوني لتدقيق حساباتها إذا زاد رأسمالها أو حجم مبيعاتها السنوية على:","o":["مائة ألف دينار","خمسين ألف دينار","مليون دينار","مائتين وخمسين ألف دينار"],"a":0},{"q":"تلتزم الشركة ذات المسؤولية المحدودة بتعيين محاسب قانوني مجاز في أي وظيفة رئيسية تتعلق بالمحاسبة إذا تجاوز رأسمالها أو حجم مبيعاتها السنوية:","o":["مليون دينار","مائة ألف دينار","خمسمائة ألف دينار","مليوني دينار"],"a":0},{"q":"غرامة التخلف عن تعيين محاسب قانوني وفق المادة (٣٠) تدفع إلى الجمعية ومقدارها:","o":["ثلاثة دنانير عن كل يوم تخلف","خمسة دنانير عن كل يوم تخلف","عشرة دنانير عن كل يوم تخلف","مائة دينار عن كل شهر تخلف"],"a":0},{"q":"الأندية الملزمة باختيار محاسب قانوني لتدقيق حساباتها هي الأندية التي تحدد بموجب قرار صادر عن:","o":["الهيئة العليا","المجلس","الوزير","وزارة الشباب"],"a":0}]},{"n":"31","chapter":"الجهات الملزمة بتعيين محاسب قانوني","notes":[],"source":"على أي جهة ملزمة بتعيين محاسب قانوني وفقا لاحكام المادة (٣٠) من هذا القانون :-\nأ-توفيق اوضاعها خلال مدة لا تتجاوز سنتين من تاريخ نفاذ احكام هذا القانون قابلة للتمديد سنة اخرى بقرار من الهيئة العليا ، اما توفيق اوضاع الشركات المنصوص عليها في الفقرة (ب) من المادة (٣٠) من هذا القانون فيتم بمقتضى تعليمات تصدرها الهيئة العليا .\nب-تزويد الجمعية باسم المحاسب القانوني خلال ثلاثين يوما من تاريخ اختياره .","title":"توفيق الأوضاع وتزويد الجمعية باسم المحاسب","memo":"⭐ توفيق الأوضاع خلال مدة لا تتجاوز سنتين من نفاذ القانون قابلة للتمديد سنة بقرار الهيئة العليا\n⭐ شركات المادة ٣٠/ب توفق أوضاعها بتعليمات الهيئة العليا\n⭐ تزويد الجمعية باسم المحاسب القانوني خلال ٣٠ يوماً من اختياره","qs":[{"q":"على الجهة الملزمة بتعيين محاسب قانوني توفيق أوضاعها خلال مدة لا تتجاوز:","o":["سنتين من تاريخ نفاذ القانون قابلة للتمديد سنة أخرى","سنة من تاريخ نفاذ القانون قابلة للتمديد سنة أخرى","ثلاث سنوات من تاريخ نفاذ القانون غير قابلة للتمديد","ستة أشهر من تاريخ نفاذ القانون"],"a":0},{"q":"على الجهة الملزمة تزويد الجمعية باسم المحاسب القانوني خلال:","o":["ثلاثين يوماً من تاريخ اختياره","ستين يوماً من تاريخ اختياره","سبعة أيام من تاريخ اختياره","ثلاثة أشهر من تاريخ اختياره"],"a":0},{"q":"تمديد مهلة توفيق الأوضاع للجهات الملزمة بتعيين محاسب قانوني يكون بقرار من:","o":["الهيئة العليا","المجلس","الوزير","مجلس الوزراء"],"a":0}]},{"n":"32","chapter":"الجهات الملزمة بتعيين محاسب قانوني","notes":[],"source":"مع مراعاة احكام قانون الشركات المعمول به لا يجوز لاي جهة تغيير المحاسب القانوني الذي تم اختياره لغايات تدقيق حساباتها خلال السنة المالية ، ويستثنى من ذلك الحالات التي يتعذر على المحاسب القانوني الاستمرار في قيامه بمهامه او اذا توقف عن العمل وفقا لاحكام هذا القانون والانظمة والتعليمات الصادرة بمقتضاه ، على ان يبلغ المجلس بذلك خلال ثلاثين يوما .","title":"حظر تغيير المحاسب خلال السنة المالية","memo":"⭐ لا يجوز تغيير المحاسب القانوني المختار للتدقيق خلال السنة المالية\n⭐ إلا إذا تعذر عليه الاستمرار أو توقف عن العمل\n⭐ على أن يبلغ المجلس خلال ٣٠ يوماً","qs":[{"q":"الأصل وفق المادة (٣٢) أنه لا يجوز لأي جهة تغيير المحاسب القانوني الذي اختارته لتدقيق حساباتها:","o":["خلال السنة المالية","قبل مرور أربع سنوات","إلا بموافقة الهيئة العامة للشركة","إلا بقرار من المحكمة"],"a":0},{"q":"حالة عملية: توقف مدقق حسابات شركة عن العمل خلال السنة المالية فاستبدلته الشركة، فعليها إبلاغ المجلس بذلك خلال:","o":["ثلاثين يوماً","ستين يوماً","خمسة عشر يوماً","سبعة أيام"],"a":0}]},{"n":"33","chapter":"الجهات الملزمة بتعيين محاسب قانوني","notes":[],"source":"لا يجوز اختيار محاسب قانوني لتدقيق حسابات الشركات المساهمة العامة والخاصة وذات المسؤولية المحدودة مدة تزيد على اربع سنوات متتالية على ان تؤخذ موافقة الهيئة العليا على ما زاد على ذلك .","title":"تدوير مدقق الحسابات","memo":"⭐ لا يجوز اختيار المحاسب نفسه لتدقيق حسابات المساهمة العامة والخاصة وذات المسؤولية المحدودة أكثر من ٤ سنوات متتالية\n⭐ ما زاد على ذلك يحتاج موافقة الهيئة العليا","qs":[{"q":"لا يجوز اختيار محاسب قانوني لتدقيق حسابات الشركات المساهمة العامة مدة تزيد على:","o":["أربع سنوات متتالية","ثلاث سنوات متتالية","خمس سنوات متتالية","سنتين متتاليتين"],"a":0},{"q":"حالة عملية: رغبت شركة ذات مسؤولية محدودة في تجديد اختيار مدققها للسنة الخامسة على التوالي، فيلزمها:","o":["أخذ موافقة الهيئة العليا","أخذ موافقة مجلس إدارة الجمعية","أخذ موافقة مراقب عام الشركات فقط","لا يلزمها أي موافقة"],"a":0}]},{"n":"34","chapter":"اللجنة التأديبية","notes":[],"source":"تشكل في الجمعية بقرار من المجلس لجنة تأديبية على ان تحدد اختصاصاتها وكيفية عقد اجتماعاتها واصدار قراراتها والتصديق عليها وتنفيذها ونشرها واجراءات تقديم الشكاوى والنظر فيها وتشكيل أي لجان اخرى لغايات قيام هذه اللجنة بمهامها بمقتضى نظام مزاولة مهنة المحاسبة القانونية الصادر بمقتضى احكام هذا القانون .","title":"تشكيل اللجنة التأديبية","memo":"⭐ تشكل في الجمعية بقرار من المجلس\n⭐ اختصاصاتها وإجراءاتها والشكاوى تحدد بنظام مزاولة مهنة المحاسبة القانونية","qs":[{"q":"تشكل اللجنة التأديبية في الجمعية بقرار من:","o":["المجلس","الهيئة العليا","الهيئة العامة","الوزير"],"a":0},{"q":"تحدد اختصاصات اللجنة التأديبية وإجراءات تقديم الشكاوى والنظر فيها بمقتضى:","o":["نظام مزاولة مهنة المحاسبة القانونية","النظام الداخلي للجمعية","تعليمات الهيئة العليا","قرار من المجلس"],"a":0}]},{"n":"35","chapter":"اللجنة التأديبية","notes":[],"source":"اذا ارتكب المحاسب القانوني او المتدرب أي مخالفة لاحكام هذا القانون والانظمة والتعليمات الصادرة بمقتضاه او اخل بواجبات عمله او بقواعد سلوك المهنة وآدابها يحيله المجلس الى اللجنة التأديبية .","title":"الإحالة إلى اللجنة التأديبية","memo":"⭐ إذا خالف المحاسب القانوني أو المتدرب أحكام القانون أو أخل بواجباته أو بقواعد السلوك\n⭐ يحيله المجلس إلى اللجنة التأديبية","qs":[{"q":"الجهة التي تحيل المحاسب القانوني المخالف إلى اللجنة التأديبية هي:","o":["المجلس","الهيئة العليا","الهيئة العامة","النيابة العامة"],"a":0},{"q":"تشمل الإحالة إلى اللجنة التأديبية وفق المادة (٣٥):","o":["المحاسب القانوني والمتدرب","المحاسب القانوني المزاول فقط","المتدرب فقط","الجهات الملزمة بتعيين محاسب قانوني"],"a":0}]},{"n":"36","chapter":"اللجنة التأديبية","notes":[],"source":"توقع اللجنة التأديبية أيا من العقوبات التأديبية التالية :-\nأ-اذا كان المخالف محاسبا قانونيا :-\n١-التنبيه .\n٢-الانذار الخطي .\n٣-تعليق التسجيل وايقاف العمل باجازة المزاولة لمدة لا تزيد على سنتين .\n٤-الغاء اجازة المزاولة وشطب اسم المحاسب القانوني نهائيا من سجل المزاولين .\nب-اذا كان المخالف متدربا :-\n١-التنبيه .\n٢-الانذار الخطي .\n٣-وقف التدريب لمدة لا تزيد على سنتين .","title":"العقوبات التأديبية","memo":"⭐ للمحاسب: التنبيه، الإنذار الخطي، تعليق التسجيل وإيقاف الإجازة مدة لا تزيد على سنتين، إلغاء الإجازة والشطب نهائياً\n⭐ للمتدرب: التنبيه، الإنذار الخطي، وقف التدريب مدة لا تزيد على سنتين","qs":[{"q":"الحد الأقصى لمدة تعليق تسجيل المحاسب القانوني وإيقاف العمل بإجازة المزاولة كعقوبة تأديبية:","o":["سنتان","سنة","ثلاث سنوات","ستة أشهر"],"a":0},{"q":"أي من العقوبات التالية لا يجوز للجنة التأديبية إيقاعها على المتدرب؟","o":["الغرامة المالية","التنبيه","الإنذار الخطي","وقف التدريب لمدة لا تزيد على سنتين"],"a":0},{"q":"أشد عقوبة تأديبية يمكن إيقاعها على المحاسب القانوني:","o":["إلغاء إجازة المزاولة وشطب اسمه نهائياً من سجل المزاولين","تعليق التسجيل لمدة لا تزيد على سنتين","الإنذار الخطي","الحبس مدة لا تزيد على ثلاث سنوات"],"a":0}]},{"n":"37","chapter":"اللجنة التأديبية","notes":[],"source":"تكون قرارات اللجنة التأديبية خاضعة لمصادقة المجلس ، ويكون قرار المجلس خاضعا لمصادقة الهيئة العليا اذا تعلق بالغاء اجازة المزاولة وشطب اسم المحاسب القانوني نهائيا من سجل المزاولين على ان تكون هذه القرارات قابلة للطعن امام محكمة العدل العليا .","title":"المصادقة على القرارات التأديبية والطعن فيها","memo":"⭐ قرارات اللجنة التأديبية تخضع لمصادقة المجلس\n⭐ قرار المجلس يخضع لمصادقة الهيئة العليا إذا تعلق بإلغاء الإجازة والشطب النهائي\n⭐ القرارات قابلة للطعن أمام محكمة العدل العليا","qs":[{"q":"تخضع قرارات اللجنة التأديبية لمصادقة:","o":["المجلس","الهيئة العليا","الهيئة العامة","الوزير"],"a":0},{"q":"يخضع قرار المجلس التأديبي لمصادقة الهيئة العليا إذا تعلق بـ:","o":["إلغاء إجازة المزاولة وشطب اسم المحاسب نهائياً","تعليق التسجيل لمدة سنتين","الإنذار الخطي","وقف التدريب"],"a":0},{"q":"يطعن في القرارات التأديبية النهائية أمام:","o":["محكمة العدل العليا","محكمة البداية","الهيئة العامة للجمعية","محكمة الاستئناف"],"a":0}]},{"n":"38","chapter":"الشؤون المالية","notes":[],"source":"تبدأ السنة المالية للجمعية في اليوم الاول من شهر تموز من كل سنة وتنتهي في اليوم الثلاثين من شهر حزيران من السنة التالية .","title":"السنة المالية للجمعية","memo":"⭐ تبدأ في ١ تموز وتنتهي في ٣٠ حزيران من السنة التالية","qs":[{"q":"تبدأ السنة المالية لجمعية المحاسبين القانونيين الأردنيين في:","o":["الأول من شهر تموز","الأول من شهر كانون الثاني","الأول من شهر نيسان","الأول من شهر تشرين الأول"],"a":0},{"q":"تنتهي السنة المالية للجمعية في:","o":["الثلاثين من شهر حزيران من السنة التالية","الحادي والثلاثين من شهر كانون الأول","الحادي والثلاثين من شهر آذار من السنة التالية","الثلاثين من شهر أيلول"],"a":0}]},{"n":"39","chapter":"الشؤون المالية","notes":[],"source":"أ- تتكون الموارد المالية للجمعية مما يلي :-\n١-رسوم التسجيل واعادة التسجيل .\n٢-رسوم مزاولة المهنة السنوية .\n٣-رسوم التدريب والامتحانات .\n٤-بدل اصدار اجازة المزاولة والبطاقة المهنية واي وثائق اخرى يصدرها المجلس .\n٥-المساعدات والتبرعات والمنح والهبات التي ترد اليها شريطة موافقة مجلس الوزراء عليها اذا كانت من مصدر غير اردني .\n٦-ريع الاموال المنقولة وغير المنقولة التي تملكها الجمعية او تستثمرها .\n٧-عوائد انشطة الجمعية .\n٨-بدل الخدمات التي تقدمها الجمعية كما يحددها المجلس .\n٩-نسبة او مبلغ مقطوع من اتعاب المحاسبين القانونيين المزاولين يحدد أي منهما بمقتضى الانظمة الصادرة وفقا لاحكام هذا القانون .\n١٠-بدل الاشتراك في مجلة الجمعية واثمان مطبوعاتها كما يحددها المجلس .\n١١-أي موارد اخرى يوافق عليها المجلس .\nب-تستوفي الجمعية الرسوم المنصوص عليها في الفقرة (أ) من هذه المادة ويحدد مقدارها وكيفية استيفائها وسائر الامور المتعلقة بها بموجب النظام الداخلي للجمعية .","title":"الموارد المالية للجمعية","memo":"⭐ رسوم التسجيل والمزاولة السنوية والتدريب والامتحانات وبدل الإجازة والبطاقة\n⭐ التبرعات والمنح من مصدر غير أردني تحتاج موافقة مجلس الوزراء\n⭐ نسبة أو مبلغ مقطوع من أتعاب المزاولين يحدد بالأنظمة\n⭐ مقدار الرسوم وكيفية استيفائها بالنظام الداخلي للجمعية","qs":[{"q":"يشترط لقبول الجمعية التبرعات والمنح والهبات من مصدر غير أردني موافقة:","o":["مجلس الوزراء","الهيئة العليا","الوزير","الهيئة العامة"],"a":0},{"q":"يحدد مقدار الرسوم التي تستوفيها الجمعية وكيفية استيفائها بموجب:","o":["النظام الداخلي للجمعية","تعليمات الهيئة العليا","قرار من المجلس","قرار من الوزير"],"a":0},{"q":"النسبة أو المبلغ المقطوع الذي تستوفيه الجمعية من أتعاب المحاسبين القانونيين المزاولين يحدد بمقتضى:","o":["الأنظمة الصادرة وفقاً لأحكام القانون","قرار من المجلس","تعليمات الهيئة العليا","قرار من الهيئة العامة"],"a":0}]},{"n":"40","chapter":"الشؤون المالية","notes":[],"source":"أ- يضع المجلس موازنة تقديرية للجمعية للسنة المالية التالية ويعرضها على الهيئة العامة مرفقة بالتقرير السنوي للمجلس والبيانات المالية الختامية للجمعية عن السنة المالية السابقة خلال مدة لا تتجاوز ثلاثة اشهر من نهاية كل سنة مالية لمناقشتها والتصديق عليها .\nب-اذا لم تتمكن الهيئة العامة من عقد اجتماعها السنوي العادي لاي سبب من الاسباب يستمر المجلس في الانفاق على اساس الموازنة السابقة الى ان تجتمع الهيئة العامة وتصادق على الموازنة التقديرية الجديدة .","title":"الموازنة التقديرية للجمعية","memo":"⭐ يضعها المجلس ويعرضها على الهيئة العامة مع التقرير السنوي والبيانات الختامية\n⭐ خلال مدة لا تتجاوز ٣ أشهر من نهاية كل سنة مالية\n⭐ إذا لم تجتمع الهيئة العامة يستمر الإنفاق على أساس الموازنة السابقة","qs":[{"q":"يضع الموازنة التقديرية للجمعية:","o":["المجلس","الهيئة العامة","الهيئة العليا","أمين الصندوق منفرداً"],"a":0},{"q":"إذا لم تتمكن الهيئة العامة من عقد اجتماعها السنوي العادي، فإن المجلس:","o":["يستمر في الإنفاق على أساس الموازنة السابقة","يتوقف عن الإنفاق لحين انعقادها","ينفق وفق الموازنة الجديدة بعد مصادقة الهيئة العليا","ينفق بموافقة الوزير"],"a":0},{"q":"يعرض المجلس الموازنة التقديرية على الهيئة العامة خلال مدة لا تتجاوز:","o":["ثلاثة أشهر من نهاية كل سنة مالية","شهرين من نهاية كل سنة مالية","ستة أشهر من نهاية كل سنة مالية","شهر من بداية السنة المالية"],"a":0}]},{"n":"41","chapter":"احكام انتقالية","notes":[],"source":"أ- يشكل وفقا لاحكام هذا القانون مجلس انتقالي مؤلف من :-\n١-رئيس واعضاء مجلس ادارة جمعية مدققي الحسابات القانونيين الأردنيين المنشأة بمقتضى قانون مهنة تدقيق الحسابات رقم (٣٢) لسنة ١٩٨٥ .\n٢-اربعة اعضاء من ذوي الخبرة يعينهم مجلس الوزراء بناء على تنسيب الوزير .\nب-يمارس المجلس الانتقالي صلاحيات المجلس ويمارس رئيس مجلس ادارة جمعية مدققي الحسابات القانونيين الأردنيين صلاحيات الرئيس وفق احكام هذا القانون وذلك الى حين اجراء انتخابات المجلس بدعوة من الهيئة العليا خلال مدة لا تتجاوز سنة من تاريخ نفاذ احكام هذا القانون .","title":"المجلس الانتقالي","memo":"⭐ يتألف من رئيس وأعضاء مجلس جمعية مدققي الحسابات القانونيين (قانون ٣٢ لسنة ١٩٨٥) + ٤ أعضاء خبرة يعينهم مجلس الوزراء بتنسيب الوزير\n⭐ يمارس صلاحيات المجلس حتى الانتخابات بدعوة من الهيئة العليا خلال سنة من نفاذ القانون","qs":[{"q":"عدد أعضاء ذوي الخبرة الذين يعينهم مجلس الوزراء في المجلس الانتقالي:","o":["أربعة","ثلاثة","خمسة","اثنان"],"a":0},{"q":"تجرى انتخابات المجلس بعد المجلس الانتقالي بدعوة من الهيئة العليا خلال مدة لا تتجاوز:","o":["سنة من تاريخ نفاذ القانون","ستة أشهر من تاريخ نفاذ القانون","سنتين من تاريخ نفاذ القانون","ثلاثة أشهر من تاريخ نفاذ القانون"],"a":0}]},{"n":"42","chapter":"احكام انتقالية","notes":[],"source":"يحق لكل شخص يعمل في المحاسبة او التدقيق ، عند نفاذ احكام هذا القانون ، ان يتقدم بطلب الى لجنة الترخيص للحصول على اجازة المزاولة خلال مدة لا تزيد على سنة من تاريخ نفاذ احكامه قابلة للتمديد سنة اخرى بقرار من الهيئة العليا على ان تتوافر فيه ما يلي :-\nأ-الشروط المحددة في الفقرات (أ) و (ب) و (ج) و (د) و (و) من المادة (٢٢) من هذا القانون .\nب-ان تكون لديه خبرة عملية في اعمال المحاسبة ضعف مدة التدريب او خبرة في التدقيق مساوية لمدة التدريب المحددة بموجب النظام الصادر بمقتضى المادة (٢٩) من هذا القانون ، على ان تحدد شروط اعتماد هذه الخبرة وطريقة احتسابها بموجب تعليمات تصدرها الهيئة العليا لهذه الغاية .","title":"الحصول على الإجازة للعاملين عند نفاذ القانون","memo":"⭐ لمن يعمل في المحاسبة أو التدقيق التقدم خلال سنة من النفاذ قابلة للتمديد سنة بقرار الهيئة العليا\n⭐ شروط المادة ٢٢ (أ،ب،ج،د،و) - دون شرط التدريب\n⭐ خبرة محاسبة ضعف مدة التدريب أو خبرة تدقيق مساوية لها","qs":[{"q":"يشترط فيمن يعمل في أعمال المحاسبة عند نفاذ القانون للحصول على الإجازة وفق المادة (٤٢) خبرة عملية:","o":["ضعف مدة التدريب","مساوية لمدة التدريب","ثلاثة أضعاف مدة التدريب","نصف مدة التدريب"],"a":0},{"q":"يشترط فيمن يعمل في أعمال التدقيق عند نفاذ القانون للحصول على الإجازة وفق المادة (٤٢) خبرة:","o":["مساوية لمدة التدريب","ضعف مدة التدريب","لا تقل عن خمس سنوات","لا تقل عن عشر سنوات"],"a":0},{"q":"أي من شروط المادة (٢٢) لا يشترط فيمن يتقدم بطلب وفق المادة (٤٢)؟","o":["استكمال متطلبات التدريب","اجتياز امتحان لجنة الترخيص","الجنسية الأردنية","المؤهل العلمي"],"a":0}]},{"n":"43","chapter":"احكام عامة","notes":[],"source":"أ-١- يعاقب بالحبس مدة لاتقل عن سنة ولا تزيد على ثلاث سنوات او بغرامة لاتقل عن خمسة الاف دينار ولا تزيد على عشرين الف دينار او بكلتا هاتين العقوبتين ، كل من خالف احكام المادة (٢١) من هذا القانون .\n٢-تطبق احكام البند (١) من هذه الفقرة على كل من زاول المهنة خلال مدة ايقاف تسجيله او بعد شطب اسمه من سجل المزاولين .\nب-في حال تكرار أي من الافعال المنصوص عليها في الفقرة (أ) من هذه المادة تكون العقوبة الحبس ولا يجوز الحكم بالغرامة في هذه الحالة .","title":"عقوبة المزاولة دون إجازة","memo":"⭐ الحبس من سنة إلى ٣ سنوات أو غرامة ٥٠٠٠ - ٢٠٠٠٠ دينار أو كلتاهما لمخالف المادة ٢١\n⭐ تطبق على من زاول خلال إيقاف تسجيله أو بعد شطبه\n⭐ عند التكرار: الحبس ولا يجوز الحكم بالغرامة","qs":[{"q":"عقوبة من يزاول أعمال التدقيق دون إجازة مزاولة:","o":["الحبس من سنة إلى ثلاث سنوات أو غرامة من خمسة آلاف إلى عشرين ألف دينار أو كلتاهما","الحبس من ستة أشهر إلى سنة أو غرامة من ألف إلى خمسة آلاف دينار","غرامة ثلاثة دنانير عن كل يوم","إلغاء الإجازة وشطب الاسم من السجل"],"a":0},{"q":"في حال تكرار مزاولة المهنة دون إجازة تكون العقوبة:","o":["الحبس ولا يجوز الحكم بالغرامة","الغرامة المضاعفة","الحبس والغرامة معاً وجوباً","الحبس أو الغرامة حسب تقدير المحكمة"],"a":0},{"q":"حالة عملية: محاسب قانوني عُلّق تسجيله لمدة سنة، فاستمر في مزاولة المهنة خلال مدة الإيقاف، فإنه:","o":["يعاقب بعقوبة مزاولة المهنة دون إجازة","يعاقب تأديبياً فقط بالإنذار الخطي","لا يعاقب لأنه حاصل على إجازة","يعاقب بغرامة ثلاثة دنانير عن كل يوم"],"a":0}]},{"n":"44","chapter":"احكام عامة","notes":[],"source":"مع عدم الاخلال باي عقوبة اشد ورد النص عليها في أي تشريع اخر ، يعاقب المحاسب القانوني بالحبس لمدة لاتقل عن سنة ولا تزيد على ثلاث سنوات او بغرامة لا تقل عن خمسة الاف دينار ولا تتجاوز عشرين الف دينار او بكلتا هاتين العقوبتين ، اذا ارتكب عن قصد او نتيجة اهمال جسيم أيا من الافعال التالية :-\nأ-دون بيانات كاذبة في أي تقرير او حسابات او وثيقة قام باعدادها اثناء مزاولة المهنة .\nب-وضع تقريرا مغايرا للحقيقة او صادق على وقائع مغايرة للحقيقة في أي وثيقة متعلقة بمزاولة المهنة .","title":"عقوبة البيانات الكاذبة والتقارير المغايرة للحقيقة","memo":"⭐ الحبس من سنة إلى ٣ سنوات أو غرامة ٥٠٠٠ - ٢٠٠٠٠ دينار أو كلتاهما\n⭐ إذا ارتكبه عن قصد أو نتيجة إهمال جسيم\n⭐ الأفعال: تدوين بيانات كاذبة، أو وضع تقرير مغاير للحقيقة أو المصادقة على وقائع مغايرة\n⭐ مع عدم الإخلال بأي عقوبة أشد في تشريع آخر","qs":[{"q":"يعاقب المحاسب القانوني الذي دون بيانات كاذبة في تقرير أعده أثناء مزاولة المهنة بغرامة:","o":["لا تقل عن خمسة آلاف دينار ولا تتجاوز عشرين ألف دينار","لا تقل عن ألف دينار ولا تتجاوز خمسة آلاف دينار","لا تقل عن عشرة آلاف دينار ولا تتجاوز خمسين ألف دينار","ثلاثة دنانير عن كل يوم"],"a":0},{"q":"تطبق عقوبة المادة (٤٤) على المحاسب القانوني إذا ارتكب الفعل:","o":["عن قصد أو نتيجة إهمال جسيم","عن قصد فقط","نتيجة أي إهمال ولو كان يسيراً","بالتواطؤ مع العميل فقط"],"a":0},{"q":"حالة عملية: مدقق صادق عمداً على وقائع مغايرة للحقيقة في وثيقة متعلقة بمزاولة المهنة، وكان تشريع آخر ينص على عقوبة أشد، فإنه:","o":["يعاقب بالعقوبة الأشد الواردة في التشريع الآخر","يعاقب بعقوبة المادة (٤٤) فقط","يحال إلى اللجنة التأديبية فقط","يعاقب بالعقوبتين معاً"],"a":0}]},{"n":"45","chapter":"احكام عامة","notes":[],"source":"يصدر مجلس الوزراء الانظمة اللازمة لتنفيذ احكام هذا القانون بما في ذلك مايلي:-\nأ-نظام مزاولة مهنة المحاسبة القانونية وذلك خلال ستة اشهر على الاكثر من تاريخ نفاذ احكام هذا القانون على ان يتضمن بصورة خاصة ما يلي :-\n١-مجالات مزاولة المهنة وشروط مزاولة كل منها واحكامها وحقوق المحاسبين القانونيين بمجالاتهم المختلفة والالتزامات المترتبة عليهم .\n٢-الاحكام المتعلقة بالتعليم المستمر للمحاسب القانوني .\n٣-تحديد اختصاصات لجان التفتيش التي يشكلها المجلس واسلوب عملها .\n٤-شروط تأسيس شركات مدنية بين المحاسبين القانونيين والمؤهلات المطلوبة ومسؤولية الشركة والمحاسبين القانونيين فيها واي امور اخرى تتعلق فيها .\nب-النظام الداخلي للجمعية على ان يتضمن على وجه الخصوص مايلي :-\n١-شروط الترشيح لعضوية المجلس واجراءاته وجميع الامور المتعلقة بالانتخابات بما في ذلك تمثيل جميع مجالات المهنة في المجلس وحالات فقد العضوية وآثارها والاستقالة من المجلس .\n٢-توزيع المهام بين اعضاء المجلس وتحديد صلاحيات الرئيس ونائبه وصلاحيات امين السر وامين الصندوق والمفوضين بالتوقيع عن المجلس في الامور المالية والادارية والقانونية وكيفية عقد الاجتماعات وتدوين محاضر الجلسات واي امور اخرى تتعلق بعمل المجلس .\n٣-تحديد مقدار الرسوم التي تستوفيها الجمعية وكيفية فرضها واستيفائها وتحصيلها وانفاقها والاجراءات المتعلقة بذلك .\n٤-انشاء فروع او فتح مكاتب للجمعية في أي مكان في المملكة .","title":"الأنظمة التنفيذية","memo":"⭐ يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ القانون\n⭐ نظام مزاولة المهنة خلال ٦ أشهر على الأكثر من النفاذ: المجالات، التعليم المستمر، لجان التفتيش، الشركات المدنية\n⭐ النظام الداخلي للجمعية: الترشيح والانتخابات، توزيع المهام، الرسوم، الفروع والمكاتب","qs":[{"q":"يصدر نظام مزاولة مهنة المحاسبة القانونية خلال مدة أقصاها:","o":["ستة أشهر من تاريخ نفاذ القانون","سنة من تاريخ نفاذ القانون","ثلاثة أشهر من تاريخ نفاذ القانون","سنتان من تاريخ نفاذ القانون"],"a":0},{"q":"تصدر الأنظمة اللازمة لتنفيذ أحكام قانون تنظيم مهنة المحاسبة القانونية عن:","o":["مجلس الوزراء","الهيئة العليا","الوزير","مجلس إدارة الجمعية"],"a":0},{"q":"شروط تأسيس الشركات المدنية بين المحاسبين القانونيين يتضمنها:","o":["نظام مزاولة مهنة المحاسبة القانونية","النظام الداخلي للجمعية","تعليمات الهيئة العليا","قانون الشركات وحده"],"a":0},{"q":"أي مما يلي يتضمنه النظام الداخلي للجمعية؟","o":["شروط الترشيح لعضوية المجلس وإجراءات الانتخابات","الأحكام المتعلقة بالتعليم المستمر للمحاسب القانوني","تحديد اختصاصات لجان التفتيش","مجالات مزاولة المهنة وشروطها"],"a":0}]},{"n":"46","chapter":"احكام عامة","notes":[],"source":"أ- تصبح الجمعية الخلف القانوني والواقعي لجمعية مدققي الحسابات القانونيين الأردنيين المنشأة بمقتضى احكام قانون مهنة تدقيق الحسابات رقم (٣٢) لسنة ١٩٨٥ وتنتقل اليها جميع موجوداتها وحقوقها وتتحمل الالتزامات المترتبة عليها اعتبارا من تاريخ نفاذ احكام هذا القانون .\nب-يعتبر المسجلون في جمعية مدققي الحسابات القانونيين الأردنيين والمسددين لجميع الالتزامات المترتبة عليهم مسجلين حكما في الجمعية .","title":"الخلافة القانونية للجمعية","memo":"⭐ الجمعية الخلف القانوني والواقعي لجمعية مدققي الحسابات القانونيين (قانون ٣٢ لسنة ١٩٨٥)\n⭐ تنتقل إليها الموجودات والحقوق وتتحمل الالتزامات من تاريخ النفاذ\n⭐ المسجلون في الجمعية السابقة المسددون لالتزاماتهم مسجلون حكماً","qs":[{"q":"أصبحت جمعية المحاسبين القانونيين الأردنيين الخلف القانوني والواقعي لـ:","o":["جمعية مدققي الحسابات القانونيين الأردنيين","نقابة المحاسبين الأردنيين","ديوان المحاسبة","الهيئة العليا لتدقيق الحسابات"],"a":0},{"q":"يعتبر المسجلون في جمعية مدققي الحسابات القانونيين الأردنيين مسجلين حكماً في الجمعية بشرط:","o":["تسديد جميع الالتزامات المترتبة عليهم","اجتياز امتحان لجنة الترخيص","تقديم طلب جديد خلال سنة","أداء اليمين مرة أخرى"],"a":0}]},{"n":"47","chapter":"احكام عامة","notes":[],"source":"على الرغم مما ورد في أي تشريع اخر ، يلتزم المحاسبون القانونيون وجميع الجهات العامة والخاصة باجراء المحاسبة والتدقيق وفقا لمعايير المحاسبة ومعايير تدقيق الحسابات المعتمدة من الهيئة العليا .","title":"الالتزام بالمعايير المعتمدة","memo":"⭐ على الرغم من أي تشريع آخر\n⭐ يلتزم المحاسبون وجميع الجهات العامة والخاصة بالمعايير المعتمدة من الهيئة العليا","qs":[{"q":"تلتزم الجهات العامة والخاصة بإجراء المحاسبة والتدقيق وفقاً لمعايير المحاسبة ومعايير تدقيق الحسابات المعتمدة من:","o":["الهيئة العليا","المجلس","وزارة المالية","ديوان المحاسبة"],"a":0},{"q":"نطاق الالتزام بالمعايير المعتمدة وفق المادة (٤٧) يشمل:","o":["المحاسبين القانونيين وجميع الجهات العامة والخاصة","المحاسبين القانونيين فقط","الشركات المساهمة العامة فقط","الجهات الخاصة دون العامة"],"a":0}]},{"n":"48","chapter":"احكام عامة","notes":[],"source":"لا تسري احكام التشريعات المتعلقة بالاجتماعات العامة على اجتماعات الجمعية التي تعقد وفقا لاحكام هذا القانون والانظمة الصادرة بمقتضاه .","title":"استثناء اجتماعات الجمعية","memo":"⭐ لا تسري تشريعات الاجتماعات العامة على اجتماعات الجمعية المعقودة وفق القانون","qs":[{"q":"وفق المادة (٤٨) فإن أحكام التشريعات المتعلقة بالاجتماعات العامة على اجتماعات الجمعية المعقودة وفق القانون:","o":["لا تسري عليها","تسري عليها بشكل كامل","تسري على الاجتماعات غير العادية فقط","تسري بموافقة الوزير"],"a":0}]},{"n":"49","chapter":"احكام عامة","notes":[],"source":"أ- يلغى قانون مهنة تدقيق الحسابات رقم (٣٢) لسنة ١٩٨٥ وتعديلاته ، على ان تبقى الانظمة والتعليمات الصادرة بمقتضاه سارية المفعول الى المدى الذي لاتتعارض فيه مع احكام هذا القانون ، الى ان تلغى او يستبدل غيرها بها خلال مدة لا تزيد على سنة من تاريخ نفاذ احكام هذا القانون .\nب-تبت الهيئة العليا في أي من الامور التي لم يرد عليها نص في هذا القانون لحين صدور الانظمة والتعليمات اللازمة لتنفيذ احكام القانون .\nج-لا يعمل باي نص ورد في أي تشريع اخر الى المدى الذي يتعارض مع احكام هذا القانون والانظمة الصادرة بمقتضاه .","title":"الإلغاء والأحكام الانتقالية للأنظمة","memo":"⭐ يلغى قانون مهنة تدقيق الحسابات رقم (٣٢) لسنة ١٩٨٥\n⭐ تبقى أنظمته وتعليماته سارية بما لا يتعارض حتى تلغى أو تستبدل خلال مدة لا تزيد على سنة\n⭐ تبت الهيئة العليا فيما لم يرد عليه نص لحين صدور الأنظمة\n⭐ لا يعمل بأي نص يتعارض مع هذا القانون","qs":[{"q":"القانون الذي ألغاه قانون تنظيم مهنة المحاسبة القانونية لسنة ٢٠٠٣ هو:","o":["قانون مهنة تدقيق الحسابات رقم (٣٢) لسنة ١٩٨٥","قانون الشركات رقم (٢٢) لسنة ١٩٩٧","قانون ديوان المحاسبة","قانون مهنة تدقيق الحسابات رقم (٧٣) لسنة ١٩٨٥"],"a":0},{"q":"تبقى الأنظمة والتعليمات الصادرة بمقتضى القانون الملغى سارية بما لا يتعارض، إلى أن تلغى أو تستبدل خلال مدة لا تزيد على:","o":["سنة من تاريخ نفاذ القانون","ستة أشهر من تاريخ نفاذ القانون","سنتين من تاريخ نفاذ القانون","ثلاثة أشهر من تاريخ نفاذ القانون"],"a":0},{"q":"تبت في الأمور التي لم يرد عليها نص في القانون لحين صدور الأنظمة والتعليمات:","o":["الهيئة العليا","المجلس","الوزير","مجلس الوزراء"],"a":0}]},{"n":"50","chapter":"احكام عامة","notes":[],"source":"رئيس الوزراء والوزراء مكلفون بتنفيذ احكام هذا القانون .","title":"تنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","qs":[{"q":"المكلفون بتنفيذ أحكام قانون تنظيم مهنة المحاسبة القانونية:","o":["رئيس الوزراء والوزراء","وزير الصناعة والتجارة وحده","الهيئة العليا","مجلس إدارة الجمعية"],"a":0}]}]};
